import {createQuestModel,MISSIONS,QUEST_BOOKS,SHELF_TOPICS,shelfBooks} from './quest-model.js';
import {createQuestView,HANDOVER_GATES,questShelfApproach} from './quest-view.js';
import {LIBRARY_SHELVES,LIBRARY_RESIDENTS} from '../world/library-layout.js';
import {worldYaw} from '../world/coordinates.js';
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function createQuestController({ui,getProgress,transact,getView,getActors,getPosition,getRoom,doc=globalThis.document,win=globalThis.window,viewFactory=createQuestView,onChange=()=>{}}){
 const $=id=>doc.querySelector('#'+id);let live=null,generation=0,modalOwned=false;const hud=$('library-quest');
 function button(id,fn,token=generation){const node=$(id);if(!node)return()=>{};let pointer=null;const downs=new Set();const handlers={pointerdown:e=>{downs.add(e.pointerId);if(downs.size>1&&pointer)pointer.cancelled=true;else pointer={id:e.pointerId,x:e.clientX,y:e.clientY,cancelled:e.button!==0||e.isPrimary===false};},pointermove:e=>{if(pointer?.id===e.pointerId&&Math.hypot(e.clientX-pointer.x,e.clientY-pointer.y)>8)pointer.cancelled=true;},pointercancel:e=>{downs.delete(e.pointerId);if(pointer)pointer.cancelled=true;},pointerup:e=>downs.delete(e.pointerId),keydown:e=>{if(e.repeat&&['Enter',' '].includes(e.key))e.preventDefault();},click:e=>{if(token!==generation||e.detail>0&&pointer?.cancelled)return;e.preventDefault();fn();}};for(const[type,fn]of Object.entries(handlers))node.addEventListener(type,fn);return()=>{for(const[type,fn]of Object.entries(handlers))node.removeEventListener(type,fn);};}
 function mountModal(title,body,mount,after){const token=generation;const ok=ui.workshop(title,body,()=>{modalOwned=true;const clean=mount?.()??[];return()=>{for(const fn of clean)fn();modalOwned=false;if(token===generation)after?.();};},{kind:'library-quest-dialog'});return ok;}
 function render(){onChange();hud.hidden=!live;if(!live)return;const s=live.model.snapshot(),m=MISSIONS[s.index];$('quest-title').textContent=`사서 도우미 ${s.index+1} / 4 · ${m.title}`;$('quest-status').textContent=live.view.busy?'책을 옮기는 중…':s.phase==='complete'?(live.savePending?'도장은 아직 저장되지 않았어요':`도장 완료 · ${m.name}`):s.held?`손에 든 책: ${QUEST_BOOKS[s.held].title} · ${m.name} 앞 금빛 원으로`:`단서: ${m.clue.split(': ')[1]??m.clue}`;$('quest-next').hidden=s.phase!=='complete';$('quest-next').disabled=live.view.busy;$('quest-next').textContent=live.savePending?'도장 저장 재시도':s.index===3?'마치기':'다음 의뢰';$('quest-clue').textContent=s.phase==='complete'?'왜 맞았을까요?':'의뢰 다시 읽기';}
 function saveCompletion(){if(!live)return false;const s=live.model.snapshot();if(s.phase!=='complete')return false;const done=getProgress().libraryQuest?.completed??[];live.savePending=!done.includes(s.missionId)&&!transact({type:'COMPLETE_LIBRARY_QUEST',id:s.missionId});render();return !live.savePending;}
 function launch(index){if(getRoom()!=='library'||live)return;const view=getView(),actors=getActors();if(!view?.root||!actors.player)return;generation++;live={model:createQuestModel(index),view:viewFactory({zoneRoot:view.root,...actors}),savePending:false,listeners:[]};live.view.setMission(index);doc.body?.classList.add('library-quest-open');
  live.listeners.push(button('quest-stop',cancel),button('quest-clue',clue),button('quest-next',()=>{if(!live||live.view.busy)return;if(live.savePending){saveCompletion();return;}if(live.model.next()){live.view.setMission(live.model.snapshot().index);render();clue();}else cancel();}));render();}
 function start(){if(live){clue();return false;}if(getRoom()!=='library')return false;generation++;face(LIBRARY_RESIDENTS.find(r=>r.id==='chinchilla').home);let choice=null;const done=getProgress().libraryQuest?.completed??[];return mountModal('친칠라 사서의 책 찾기 의뢰',`<p><strong>친칠라 사서</strong> · 어서 와요, 도름이! 친구들에게 필요한 책을 함께 찾아 줄래요? 아래에서 의뢰를 골라 주세요.</p><p>단서를 읽고 → 책장으로 걸어가 책을 살펴보고 → 손에 들고 직접 전달해요. 시간 제한은 없어요.</p><p>도우미를 그만두면 빌리기와 의자에서 읽기를 다시 할 수 있어요. 빌린 책은 그대로예요.</p><div class="quest-missions">${MISSIONS.map((m,i)=>`<button id="quest-start-${i}"><strong>${i+1}. ${m.title}</strong><span>${done.includes(m.id)?'도장 있음 · 다시 놀이':'새 의뢰'}</span><span>${escape(m.clue)}</span></button>`).join('')}</div>`,()=>MISSIONS.map((m,i)=>button('quest-start-'+i,()=>{choice=i;ui.close();})),()=>{if(choice!==null)launch(choice);});}
 function clue(){if(!live||ui.modalOpen)return;const s=live.model.snapshot(),m=MISSIONS[s.index];mountModal(s.phase==='complete'?'책 속 근거를 찾았어요':m.title,`<p>${escape(s.phase==='complete'?m.reason:m.clue)}</p><p class="quest-small">${s.phase==='complete'?'도장은 의뢰마다 한 번만 남아요. 같은 의뢰도 다시 놀 수 있어요.':'책장 앞 작은 초록 원에 서서 살펴봐요. 건넬 때는 친구 앞 금빛 원으로 가요. E / 행동으로 가까운 책장을 읽고, 이동키나 방향 버튼으로 직접 가져가요.'}</p><button id="quest-clue-close" class="primary">${s.phase==='complete'?'계속':'찾으러 가기'}</button>`,()=>[button('quest-clue-close',()=>ui.close())]);}
 function nearby(){if(!live||getRoom()!=='library'||live.view.busy||live.model.snapshot().phase==='complete')return null;const p=getPosition(),s=live.model.snapshot();const targets=[...LIBRARY_SHELVES.map((v,i)=>({id:'quest.shelf.'+i,type:'libraryQuestShelf',shelf:i,at:questShelfApproach(i),radius:.16,label:s.held?(MISSIONS[s.index].kind==='sort'?'이 책장에 꽂기':'책장에 돌려놓기'):`${i+1} · ${SHELF_TOPICS[i]} 책장 살펴보기`})),...LIBRARY_RESIDENTS.map(r=>({id:'quest.recipient.'+r.id,type:'libraryQuestRecipient',residentId:r.id,at:s.held?HANDOVER_GATES[r.id]:r.talkAt,radius:s.held?.15:r.interactionRadius??1,label:s.held?`${r.name}에게 책 건네기`:`${r.name}의 의뢰 듣기`}))];return targets.filter(t=>Math.hypot(t.at.x-p.x,t.at.z-p.z)<=t.radius).sort((a,b)=>Math.hypot(a.at.x-p.x,a.at.z-p.z)-Math.hypot(b.at.x-p.x,b.at.z-p.z))[0]??null;}
 function face(at){const {player}=getActors(),p=getPosition();player.rotation.set(0,worldYaw('library',Math.atan2(at.x-p.x,at.z-p.z)),0);}
 function wrong(message){if(live)live.lastMessage=message;render();mountModal('단서를 다시 살펴봐요',`<p>${escape(message)}</p><button id="quest-wrong-close" class="primary">다시 찾아볼게요</button>`,()=>[button('quest-wrong-close',()=>ui.close())]);}
 function interact(target){if(!live||live.view.busy||!target||ui.modalOpen)return false;const near=nearby();if(!near||near.id!==target.id)return false;const s=live.model.snapshot(),m=MISSIONS[s.index];if(target.type==='libraryQuestRecipient'){if(!s.held){clue();return true;}const result=live.model.deliver(target.residentId);if(!result.ok){wrong(result.message);return true;}face(LIBRARY_RESIDENTS.find(r=>r.id===target.residentId).home);live.view.deliver();live.awaitAward=true;render();return true;}
  if(target.type!=='libraryQuestShelf')return false;const shelf=target.shelf;
  if(s.held){if(m.kind==='sort'&&s.held===m.bookId&&shelf===m.recipient){const result=live.model.deliver(shelf);if(result.ok){face(LIBRARY_SHELVES[shelf]);live.view.deliver();live.awaitAward=true;render();return true;}}if(live.model.returnBook(shelf)){face(LIBRARY_SHELVES[shelf]);live.view.returnBook();render();}else wrong(`이 책은 ${s.source+1} · ${SHELF_TOPICS[s.source]} 책장에서 가져왔어요.${m.kind==='sort'?' 의뢰에 맞는 주제 책장도 찾아봐요.':' 먼저 그곳에 돌려놓아요.'}`);return true;}
  let selected=null,pick=null;const ids=shelfBooks(s.index,shelf);mountModal(`${shelf+1} · ${SHELF_TOPICS[shelf]} 책장`,`<p>이 책장에 놓인 책이에요. 한 권을 펼쳐 내용을 읽어 봐요.</p><div class="quest-books">${ids.map(id=>`<button id="quest-read-${id}">${escape(QUEST_BOOKS[id].title)}</button>`).join('')||'<p>지금은 책 한 권이 다른 책장에 가 있어요.</p>'}</div><article id="quest-page" class="quest-page" aria-live="polite"></article><button id="quest-pick" class="primary" disabled>이 책을 손에 들기</button>`,()=>{const cleaners=ids.map(id=>button('quest-read-'+id,()=>{if(!live?.model.inspect(id,shelf))return;selected=id;const b=QUEST_BOOKS[id];$('quest-page').innerHTML=`<h3>${escape(b.title)}</h3><p>${escape(b.text)}</p>`;$('quest-pick').disabled=false;}));cleaners.push(button('quest-pick',()=>{if(selected&&live?.model.pick(selected,shelf)){pick=selected;ui.close();}}));return cleaners;},()=>{if(pick&&live){face(LIBRARY_SHELVES[shelf]);live.view.pick(pick);render();}});return true;
 }
 function tick(dt){if(!live)return;if(getRoom()!=='library'){cancel();return;}if(ui.modalOpen||doc.hidden)return;const busy=live.view.busy;live.view.tick(dt);if(live.awaitAward&&!live.view.busy){live.awaitAward=false;saveCompletion();ui.toast('책을 직접 전했어요! 책 속 근거도 확인해 봐요',3500);}if(busy!==live.view.busy)render();}
 function cancel(){generation++;const old=live;live=null;if(old){for(const fn of old.listeners)fn();old.view.dispose();}render();doc.body?.classList.remove('library-quest-open');if(modalOwned)ui.close();}
 win.addEventListener('pagehide',cancel);return{start,interact,nearby,tick,cancel,clue,get active(){return !!live;},get busy(){return !!live?.view.busy;},get carrying(){return live?.model.snapshot().phase==='carrying';},snapshot:()=>live?{...live.model.snapshot(),savePending:live.savePending,busy:live.view.busy}:null};
}
